import java.util.ArrayList;
import java.util.List;

public final class Dedupe {
    private Dedupe() {}

    /** Distinct values from xs, first-occurrence order preserved. */
    public static List<Integer> distinct(int[] xs) {
        List<Integer> out = new ArrayList<>();
        for (int x : xs) {
            if (!out.contains(x)) {
                out.add(x);
            }
        }
        return out;
    }
}

