public final class DedupeTest {
    public static void main(String[] args) {
        checkOrder();
        checkPerformance();
        System.out.println("all tests passed");
    }

    static void checkOrder() {
        int[] xs = {5, 3, 5, 1, 3, 9, 1};
        java.util.List<Integer> got = Dedupe.distinct(xs);
        java.util.List<Integer> expected = java.util.List.of(5, 3, 1, 9);
        if (!got.equals(expected)) {
            throw new AssertionError("distinct(...) = " + got + ", expected " + expected
                    + " (first-occurrence order)");
        }
    }

    static void checkPerformance() {
        int n = 150000;
        int[] xs = new int[n];
        for (int i = 0; i < n; i++) {
            xs[i] = i;
        }
        long start = System.nanoTime();
        java.util.List<Integer> got = Dedupe.distinct(xs);
        double elapsed = (System.nanoTime() - start) / 1e9;

        if (got.size() != n || !got.get(0).equals(0) || !got.get(n - 1).equals(n - 1)) {
            throw new AssertionError("large-input result wrong");
        }
        // calibrated: List.contains per element is ~3.2s on fast native
        // hardware at n=150000 all-unique and slower in the sandbox;
        // LinkedHashSet is ~0.01s
        if (elapsed >= 1.5) {
            throw new AssertionError(String.format(
                    "distinct took %.2fs for %d values; expected a "
                    + "LinkedHashSet, not List.contains per element (O(n^2))",
                    elapsed, n));
        }
    }
}

